const militaryRole=renderRole;
const researchLabels={agriculture:'Food & farming',industry:'Building & industry',arms:'Military equipment'};
const researchSymbols={agriculture:'🌾',industry:'🛠',arms:'🛡'};
renderRole=function(){militaryRole();if(role!=='research')return;const c=ctry(),school=Society.curricula[c.education],population=Game.totals(state,active).population;
$('rolePanel').innerHTML=`<p class="role-intro">Your ideas shape every role. Divide the research budget, choose what schools teach, and balance laws with people's happiness.</p><section id="researchNational" class="allocation-panel"><div class="section-kicker">1 / INVEST IN IDEAS</div><h3>One budget. Three paths.</h3><p>Economy offers <b>${c.funding} money / turn</b>. Split it below. Each field keeps its progress.</p><form id="researchAllocationForm"><div class="allocation-presets"><button type="button" data-research-preset="34,33,33">Balanced</button><button type="button" data-research-preset="60,25,15">Grow food</button><button type="button" data-research-preset="25,60,15">Build</button><button type="button" data-research-preset="20,20,60">Defend</button></div><div class="allocation-bar" id="researchBar" aria-hidden="true"></div>${Object.keys(Research.catalog).map(key=>{const next=Research.achievement(key,c.tech[key]),need=Game.projects[key].cost*(c.tech[key]+1),progress=c.researchBank[key];return `<article class="research-path achievement"><img src="research-images/${next?.id||Research.catalog[key][3][0]}.svg" alt="${next?.name||'Field completed'}"><div><label for="research-${key}">${researchSymbols[key]} ${researchLabels[key]}</label><b>${next?next.name:'✓ All discoveries earned'}</b><small>${next?next.bonus:'This share stays unspent until reassigned.'}</small><progress value="${progress}" max="${need}" aria-label="${researchLabels[key]} discovery progress"></progress><small>${progress.toFixed(1)} / ${need} points</small></div><label class="share-input">Share %<input id="research-${key}" data-research-share="${key}" type="number" min="0" max="100" step="1" value="${c.researchShares[key]}"></label><p class="research-estimate" id="research-estimate-${key}"></p></article>`;}).join('')}<p id="researchAllocationStatus" class="allocation-status" role="status"></p><button id="applyResearch" class="primary" type="submit">Apply research split</button></form><p class="micro-help">Shares must total 100%. Education is paid first. A field without its kit pauses and keeps its money. When materials are scarce, kits are checked in the order shown. Completed fields do not spend their share.</p>${c.researchReport?`<div class="last-use"><b>Last Results · turn ${c.researchReport.turn}</b>${c.researchReport.fields.map(f=>`<p>${researchSymbols[f.key]} ${researchLabels[f.key]}: ${f.spent.toFixed(1)} money → ${f.points.toFixed(1)} points${f.reason?' · '+esc(f.reason):''}</p>`).join('')||'<p>No research spending.</p>'}</div>`:''}</section>
<details class="policy-workspace" id="schoolLaws"><summary>2 / Schools & laws <span>Balance growth with happiness</span></summary>${field('What do our schools teach?','education',Object.entries(Society.curricula).map(([k,p])=>[k,p.icon+' '+p.name]),c.education)}<article class="policy-preview"><span class="policy-icon">${school.icon}</span><div><h3>${school.name}</h3><p>${school.description}</p><small>School cost: ${(population*school.rate).toFixed(1)} money / turn. Learning level: ${Math.round(c.literacy)}%. Unpaid schooling slows learning.</small><progress value="${c.literacy}" max="100" aria-label="Learning level"></progress></div></article><h3>Choose laws that support your plan</h3><p class="micro-help">Laws continue each turn until changed. Happier places attract residents. Unrest makes negative social events more likely.</p>${Object.entries(Society.laws).map(([group,law])=>{const selected=law.options[c.laws[group]];return `<div class="law-card">${field(law.name,'law-'+group,Object.entries(law.options).map(([k,p])=>[k,p.icon+' '+p.name]),c.laws[group])}<p>${selected.description}</p>${group==='service'&&c.laws.service==='conscription'?`<small>${Society.draftReason(state,c)?'⚠ '+Society.draftReason(state,c):'✓ Resources and residents available now.'} Military chooses a receiving regiment in a home settlement.</small>`:''}</div>`;}).join('')}</details>
<details class="collection"><summary>Your discovery collection · 12 discoveries</summary><div class="discovery-grid">${Object.keys(Research.catalog).flatMap(key=>Research.catalog[key].map((a,i)=>{const item=Research.achievement(key,i),done=c.tech[key]>i;return `<article class="discovery ${done?'unlocked':'locked'}"><img src="research-images/${item.id}.svg" alt="${item.name}"><strong>${done?'✓':'○'} ${item.name}</strong><small>${item.bonus}</small></article>`;})).join('')}</div><p>Pictures celebrate an achievement. The bonus changes your country's stats; these items do not need to be moved.</p></details>`;
const values=()=>Object.fromEntries(Object.keys(Research.catalog).map(k=>[k,Number($('research-'+k).value)]));
function preview(){const shares=values(),sum=Object.values(shares).reduce((n,v)=>n+v,0),valid=Society.shares(shares,Object.keys(Research.catalog)),draft={...c,researchShares:valid?shares:c.researchShares};$('researchBar').innerHTML=Object.keys(Research.catalog).map(k=>`<span class="segment-${k}" style="flex:${Math.max(0,shares[k])||0}"></span>`).join('');const changed=JSON.stringify(shares)!==JSON.stringify(c.researchShares);$('researchAllocationStatus').textContent=valid?(state.phase!=='implement'?'Plan locked until the next Implement phase.':changed?'100% allocated · Unsaved changes. Apply to save.':'✓ Saved research split · 100% allocated.'):`${Number.isFinite(sum)?sum:0}% of 100% allocated. Adjust the shares to total 100%.`;$('applyResearch').disabled=!valid||state.phase!=='implement';for(const p of Research.plans(draft)){const points=p.money*.6*Society.researchRate(c,p.key)*(.65+c.literacy/100);$('research-estimate-'+p.key).textContent=`${p.money.toFixed(1)} money → about ${points.toFixed(1)} points + school bonus · Kit: ${Object.entries(p.cost).filter(([k,n])=>n).map(([k,n])=>n+' '+k).join(', ')||'none'}`;}}
$('researchAllocationForm').onsubmit=e=>{e.preventDefault();action(()=>Research.allocate(state,active,values()),'Research allocation saved. Progress in every field is kept.');};$('rolePanel').querySelectorAll('[data-research-share]').forEach(e=>e.oninput=preview);$('rolePanel').querySelectorAll('[data-research-preset]').forEach(b=>b.onclick=()=>{b.dataset.researchPreset.split(',').forEach((v,i)=>$('research-'+Object.keys(Research.catalog)[i]).value=v);preview();});
$('education').onchange=e=>{action(()=>Society.setSchool(state,active,e.target.value),'School curriculum saved.');$('schoolLaws').open=true;};for(const group of Object.keys(Society.laws))$('law-'+group).onchange=e=>{action(()=>Society.setLaw(state,active,group,e.target.value),'Law saved. Check its costs and public response before Results.');$('schoolLaws').open=true;};preview();if(state.phase!=='implement')$('rolePanel').querySelectorAll('input,select,button').forEach(el=>el.disabled=true);};
render();
